             (val_mul, ":total_change", ":prosperity"),
             (val_mul, ":total_change", ":home_health"),
             (val_div, ":total_change", 260000), # (30 + prosperity) / 130 * 5% of the sales, scaled by home health.
             (val_add, ":total_change", ":producer_bonus"),

             #Adding tax revenue to the center
             (party_get_slot, ":accumulated_tariffs", ":home_center", slot_center_accumulated_tariffs),
             (val_max, ":accumulated_tariffs", 0),
             (val_max, ":total_change", 0),
