             (val_max, ":home_tariff_change", 0),
             (val_add, ":accumulated_tariffs", ":home_tariff_change"),
             (val_min, ":accumulated_tariffs", 2000000),
             (party_set_slot, ":home_center", slot_center_accumulated_tariffs, ":accumulated_tariffs"),

